SELECT IF(
  (SELECT COUNT(*) FROM information_schema.tables t JOIN expected_table e ON e.table_name=t.table_name
    WHERE t.table_schema=DATABASE() AND t.table_type='BASE TABLE' AND UPPER(t.engine)='INNODB' AND LOWER(t.table_collation)='utf8mb4_bin')=4
  AND (SELECT COUNT(*) FROM actual_view)=4
  AND NOT EXISTS (SELECT 1 FROM expected_column e LEFT JOIN actual_column a USING(table_name,column_name)
    WHERE a.table_name IS NULL OR a.column_type<>e.column_type OR a.is_nullable<>e.is_nullable OR a.character_set_name<>e.character_set_name
      OR a.collation_name<>e.collation_name OR a.default_signature<>e.default_signature OR a.extra<>e.extra OR a.generation_expression<>'')
  AND NOT EXISTS (SELECT 1 FROM expected_index e LEFT JOIN actual_index a USING(table_name,index_name)
    WHERE a.table_name IS NULL OR a.non_unique<>e.non_unique OR a.index_columns<>e.index_columns OR a.safe_shape<>1)
  AND NOT EXISTS (SELECT 1 FROM actual_column a LEFT JOIN expected_column e USING(table_name,column_name)
    WHERE e.table_name IS NULL AND NOT (a.extra NOT LIKE '%auto_increment%'
      AND (a.is_nullable='YES' OR a.default_signature<>'#NULL' OR a.generation_expression<>'')))
  AND NOT EXISTS (SELECT 1 FROM actual_index a LEFT JOIN expected_index e USING(table_name,index_name)
    WHERE e.table_name IS NULL AND NOT (a.non_unique=1 AND a.safe_shape=1))
  AND NOT EXISTS (SELECT 1 FROM expected_check e LEFT JOIN actual_check a USING(table_name,constraint_name)
    WHERE a.table_name IS NULL OR a.enforced<>'YES' OR a.clause_sha256<>e.clause_sha256)
  AND NOT EXISTS (SELECT 1 FROM expected_fk e LEFT JOIN actual_fk a USING(table_name,constraint_name)
    WHERE a.table_name IS NULL OR a.child_columns<>e.child_columns OR a.referenced_table_name<>e.referenced_table_name
      OR a.referenced_columns<>e.referenced_columns OR a.delete_rule<>e.delete_rule OR a.update_rule<>e.update_rule)
  AND NOT EXISTS (SELECT 1 FROM expected_view e LEFT JOIN actual_view a USING(table_name)
    WHERE a.table_name IS NULL OR a.view_columns<>e.view_columns OR a.security_type<>'INVOKER'
      OR a.check_option<>'NONE' OR a.is_updatable<>'NO')
  AND (SELECT COUNT(*) FROM information_schema.triggers tr JOIN expected_table e ON e.table_name=tr.event_object_table WHERE tr.trigger_schema=DATABASE())=0
  AND (SELECT COUNT(*) FROM actual_view WHERE table_name='dp_pull_advertising_sealed_current_generation'
    AND view_definition LIKE '%dp_pull_advertising_current_head%join%dp_pull_advertising_generation%'
    AND view_definition LIKE '%state=%sealed%campaign_fact_count=%selectcount%dp_pull_advertising_campaign_fact%'
    AND view_definition LIKE '%query_fact_count=%selectcount%dp_pull_advertising_query_fact%')=1
  AND (SELECT COUNT(*) FROM actual_view WHERE table_name='noon_ad_effective_report_batch'
    AND view_definition LIKE '%noon_ad_report_batch%wherenotexists%dp_pull_advertising_current_head%unionall%dp_pull_advertising_sealed_current_generation%')=1
  AND (SELECT COUNT(*) FROM actual_view WHERE table_name='noon_ad_effective_campaign_fact'
    AND view_definition LIKE '%noon_ad_campaign_fact%wherenotexists%dp_pull_advertising_current_head%unionall%dp_pull_advertising_campaign_fact%')=1
  AND (SELECT COUNT(*) FROM actual_view WHERE table_name='noon_ad_effective_query_fact'
    AND view_definition LIKE '%noon_ad_query_fact%wherenotexists%dp_pull_advertising_current_head%unionall%dp_pull_advertising_query_fact%')=1
  AND NOT EXISTS (SELECT 1 FROM generation_shape WHERE actual_campaign_count<>campaign_fact_count OR actual_query_count<>query_fact_count)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_generation
    WHERE state='SEALED' AND matched_active_campaign_count<>active_campaign_count)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_generation g LEFT JOIN dp_pull_task t ON t.id=g.task_id
    WHERE t.id IS NULL OR t.operation_code<>'DP06' OR t.owner_user_id<>g.owner_user_id
      OR NOT (BINARY t.project_code<=>BINARY g.project_code) OR NOT (BINARY t.store_code<=>BINARY g.store_code)
      OR NOT (BINARY t.site_code<=>BINARY g.site_code) OR t.schedule_slot<>g.schedule_slot
      OR NOT (BINARY t.business_window_key<=>BINARY g.business_window_key)
      OR g.active_fence_epoch>t.fence_epoch OR g.gmt_updated<g.gmt_create)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_campaign_fact c JOIN dp_pull_advertising_generation g ON g.task_id=c.task_id
    WHERE c.batch_id<>g.batch_id OR c.owner_user_id<>g.owner_user_id OR BINARY c.project_code<>BINARY g.project_code
      OR BINARY c.store_code<>BINARY g.store_code OR BINARY c.site_code<>BINARY g.site_code
      OR c.report_date_from<>g.report_date OR c.report_date_to<>g.report_date OR BINARY c.source_system<>BINARY 'noon_ads'
      OR c.id<g.campaign_id_start OR c.id-g.campaign_id_start>=g.staged_campaign_item_count
      OR (c.raw_payload_json IS NOT NULL AND NOT JSON_VALID(c.raw_payload_json)) OR c.gmt_updated<c.gmt_create)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_query_fact q JOIN dp_pull_advertising_generation g ON g.task_id=q.task_id
    WHERE q.batch_id<>g.batch_id OR q.owner_user_id<>g.owner_user_id OR BINARY q.project_code<>BINARY g.project_code
      OR BINARY q.store_code<>BINARY g.store_code OR BINARY q.site_code<>BINARY g.site_code
      OR q.report_date_from<>g.report_date OR q.report_date_to<>g.report_date OR BINARY q.source_system<>BINARY 'noon_ads'
      OR q.id<g.query_id_start OR q.id-g.query_id_start>=g.staged_item_count-g.staged_campaign_item_count-g.active_campaign_count
      OR (q.raw_payload_json IS NOT NULL AND NOT JSON_VALID(q.raw_payload_json)) OR q.gmt_updated<q.gmt_create)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_query_fact q LEFT JOIN dp_pull_advertising_campaign_fact c
    ON c.task_id=q.task_id AND c.campaign_code=q.campaign_code WHERE c.task_id IS NULL)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_current_head h LEFT JOIN dp_pull_advertising_generation g
    ON g.task_id=h.task_id AND g.batch_id=h.batch_id WHERE g.task_id IS NULL OR g.state<>'SEALED'
      OR h.owner_user_id<>g.owner_user_id OR BINARY h.project_code<>BINARY g.project_code OR BINARY h.store_code<>BINARY g.store_code
      OR BINARY h.site_code<>BINARY g.site_code OR h.report_date<>g.report_date OR h.schedule_slot<>g.schedule_slot
      OR h.authority_token_sha256<>g.authority_token_sha256 OR h.source_digest_sha256<>g.source_digest_sha256 OR h.gmt_updated<h.gmt_create)
  AND (SELECT COUNT(*) FROM dp_pull_advertising_sealed_current_generation)=(SELECT COUNT(*) FROM dp_pull_advertising_current_head)
  AND NOT EXISTS (SELECT 1 FROM dp_pull_advertising_current_head h JOIN dp_pull_advertising_generation g ON g.task_id=h.task_id
    WHERE (SELECT COUNT(*) FROM noon_ad_effective_report_batch b WHERE b.id=h.batch_id)<>1
      OR (SELECT COUNT(*) FROM noon_ad_effective_campaign_fact c WHERE c.batch_id=h.batch_id)<>g.campaign_fact_count
      OR (SELECT COUNT(*) FROM noon_ad_effective_query_fact q WHERE q.batch_id=h.batch_id)<>g.query_fact_count)
  AND (SELECT COUNT(*) FROM noon_ad_id_sequence WHERE sequence_name IN ('noon_ad_report_batch','noon_ad_campaign_fact','noon_ad_query_fact'))=3
  AND (SELECT COUNT(*) FROM noon_ad_id_sequence WHERE sequence_name='noon_ad_report_batch'
    AND next_id>=GREATEST(200000,COALESCE((SELECT MAX(id) FROM noon_ad_report_batch),0),COALESCE((SELECT MAX(batch_id) FROM dp_pull_advertising_generation),0)))=1
  AND (SELECT COUNT(*) FROM noon_ad_id_sequence WHERE sequence_name='noon_ad_campaign_fact'
    AND next_id>=GREATEST(210000,COALESCE((SELECT MAX(id) FROM noon_ad_campaign_fact),0),COALESCE((SELECT MAX(id) FROM dp_pull_advertising_campaign_fact),0)))=1
  AND (SELECT COUNT(*) FROM noon_ad_id_sequence WHERE sequence_name='noon_ad_query_fact'
    AND next_id>=GREATEST(220000,COALESCE((SELECT MAX(id) FROM noon_ad_query_fact),0),COALESCE((SELECT MAX(id) FROM dp_pull_advertising_query_fact),0)))=1,
  1,0
) AS dp246_additive_livecheck;
